ob_start();define('MAUTIC_ROOT_DIR','/var/www/html');define('IN_MAUTIC_CONSOLE',1);require MAUTIC_ROOT_DIR.'/autoload.php';$k=new AppKernel('prod',false);$k->boot();$container=$k->getContainer();$em=$container->get('doctrine')->getManager();$c=$em->getConnection();
