// Exercise the installed native form subscriber while replacing only the SMTP-producing model.
// No mail transport is created or invoked by this test.
class ANPCaptureEmailModel extends \Mautic\EmailBundle\Model\EmailModel {
 private $emailEntity;public $calls=[];public function __construct($email){$this->emailEntity=$email;}
 public function getEntity($id=null){if((int)$id!==71)throw new RuntimeException('Unexpected welcome email');return $this->emailEntity;}
 public function sendEmail(\Mautic\EmailBundle\Entity\Email $email,$leads,$options=[]){$this->calls[]=['email'=>$email->getId(),'recipient'=>$leads['email'],'source'=>$options['source']];return [];}
}
$welcome=$em->getRepository(\Mautic\EmailBundle\Entity\Email::class)->find(71);check($welcome->isPublished(),'welcome available now');$capture=new ANPCaptureEmailModel($welcome);$tracker=(new ReflectionClass(\Mautic\LeadBundle\Tracker\ContactTracker::class))->newInstanceWithoutConstructor();$subscriber=new \Mautic\EmailBundle\EventListener\FormSubscriber($capture,$tracker);$action=$em->getRepository(\Mautic\FormBundle\Entity\Action::class)->find($actionId);
for($i=0;$i<2;$i++){$event=new \Mautic\FormBundle\Event\SubmissionEvent(new \Mautic\FormBundle\Entity\Submission(),[],[],\Symfony\Component\HttpFoundation\Request::create('/form/submit','POST'));$event->setAction($action);$event->setContext('email.send.lead');$event->setActionFeedback('lead.create',['lead'=>['id'=>0,'firstname'=>'QA sem envio','email'=>'qa-anp-capture@example.com']]);$subscriber->onFormSubmitActionSendEmail($event);}
check(count($capture->calls)===2,'each successful form event invokes welcome immediately, including repeat signup');foreach($capture->calls as $call)check((int)$call['email']===71&&$call['source']===['form',12],'native subscriber uses correct form and campaign email');echo 'PASS no SMTP invoked during captured form-action test'.PHP_EOL;
$segmentEmail=$em->getRepository(\Mautic\EmailBundle\Entity\Email::class)->find(72);check(!$segmentEmail->isPublished(),'D5 not sent before its publication window');
echo 'SUMMARY '.json_encode(['welcome_email'=>71,'form_action'=>$actionId,'segment'=>33,'segment_emails'=>[72,73,74,75,76,77,78],'archived_campaign'=>36]).PHP_EOL;
